    21	public class ReservationController {
    22	  private static final ObjectMapper objectMapper = new ObjectMapper();
    23	  private static final ReservationRepository reservationRepository = new ReservationRepository();
    24	  private static final RoomRepository roomRepository = new RoomRepository();
    25	  private static final MessageRepository messageRepository = new MessageRepository();
