    29	  public static void routes(Javalin app) {
    30	    app.post("/reservations", ctx -> {
    31	      try {
    32	        ReservationRequest req = ctx.bodyAsClass(ReservationRequest.class);
    33	
    34	        if (req.roomNumber == 0 || req.guestName == null || req.guestEmail == null || req.guestCpf == null
    35	            || req.checkIn == null || req.checkOut == null || req.guests == 0 || req.ratePlan == null) {
    36	          ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Missing required fields"));
    37	          return;
    38	        }
    39	
    40	        LocalDate checkIn, checkOut;
    41	        try {
    42	          checkIn = LocalDate.parse(req.checkIn);
    43	          checkOut = LocalDate.parse(req.checkOut);
    44	        } catch (DateTimeParseException e) {
    45	          ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
    46	          return;
    47	        }
    48	
    49	        Reservation.RatePlan ratePlan;
    50	        try {
    51	          ratePlan = Reservation.RatePlan.valueOf(req.ratePlan.toUpperCase());
    52	        } catch (IllegalArgumentException e) {
    53	          ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid rate plan"));
    54	          return;
    55	        }
    56	
    57	        Reservation reservation = reservationService.createReservation(
    58	            req.roomNumber, req.guestName, req.guestEmail, req.guestCpf, checkIn, checkOut, req.guests, ratePlan,
    59	            req.companyCode);
    60	
    61	        ctx.status(201).json(toJson(reservation));
    62	      } catch (RatePlanStrategy.InvalidReservationException e) {
    63	        if (e.errorCode.equals("ROOM_NOT_FOUND")) {
    64	          ctx.status(404).json(Map.of("error", "ROOM_NOT_FOUND", "message", e.getMessage()));
    65	        } else if (e.errorCode.equals("ROOM_UNAVAILABLE")) {
    66	          ctx.status(409).json(Map.of("error", "ROOM_UNAVAILABLE", "message", e.getMessage()));
    67	        } else if (e.errorCode.equals("CAPACITY_EXCEEDED")) {
    68	          ctx.status(422).json(Map.of("error", "CAPACITY_EXCEEDED", "message", e.getMessage()));
    69	        } else {
    70	          ctx.status(400).json(Map.of("error", e.errorCode, "message", e.getMessage()));
    71	        }
    72	      }
    73	    });
    74	
    75	    app.get("/reservations/:id", ctx -> {
    76	      try {
    77	        long id = Long.parseLong(ctx.pathParam("id"));
    78	        Optional<Reservation> reservation = reservationRepository.findById(id);
    79	
    80	        if (reservation.isEmpty()) {
    81	          ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
    82	          return;
    83	        }
    84	
    85	        ctx.json(toJson(reservation.get()));
    86	      } catch (NumberFormatException e) {
    87	        ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid reservation ID"));
    88	      }
    89	    });
    90	
    91	    app.post("/reservations/:id/confirmation", ctx -> {
    92	      try {
    93	        long id = Long.parseLong(ctx.pathParam("id"));
    94	        String body = ctx.body();
    95	
    96	        BigDecimal amountPaid = BigDecimal.ZERO;
    97	        if (body != null && !body.isEmpty()) {
    98	          Map<String, Object> map = objectMapper.readValue(body, Map.class);
    99	          if (map.containsKey("amountPaid")) {
   100	            amountPaid = new BigDecimal(map.get("amountPaid").toString());
   101	          }
   102	        }
   103	
   104	        Reservation reservation = reservationService.confirmReservation(id, amountPaid);
   105	        ctx.json(toJson(reservation));
   106	      } catch (NumberFormatException e) {
   107	        ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid reservation ID"));
   108	      } catch (RatePlanStrategy.InvalidReservationException e) {
   109	        if (e.errorCode.equals("RESERVATION_NOT_FOUND")) {
   110	          ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", e.getMessage()));
   111	        } else {
   112	          ctx.status(409).json(Map.of("error", e.errorCode, "message", e.getMessage()));
   113	        }
   114	      }
   115	    });
   116	
   117	    app.post("/reservations/:id/cancellation", ctx -> {
   118	      try {
   119	        long id = Long.parseLong(ctx.pathParam("id"));
   120	        Reservation reservation = reservationService.cancel(id);
   121	        ctx.json(toJson(reservation));
   122	      } catch (NumberFormatException e) {
   123	        ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid reservation ID"));
   124	      } catch (RatePlanStrategy.InvalidReservationException e) {
   125	        if (e.errorCode.equals("RESERVATION_NOT_FOUND")) {
   126	          ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", e.getMessage()));
   127	        } else {
   128	          ctx.status(409).json(Map.of("error", e.errorCode, "message", e.getMessage()));
   129	        }
   130	      }
   131	    });
   132	
   133	    app.post("/reservations/:id/check-in", ctx -> {
   134	      try {
   135	        long id = Long.parseLong(ctx.pathParam("id"));
   136	        Reservation reservation = reservationService.checkIn(id);
   137	        ctx.json(toJson(reservation));
   138	      } catch (NumberFormatException e) {
   139	        ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid reservation ID"));
   140	      } catch (RatePlanStrategy.InvalidReservationException e) {
   141	        if (e.errorCode.equals("RESERVATION_NOT_FOUND")) {
   142	          ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", e.getMessage()));
   143	        } else {
   144	          ctx.status(409).json(Map.of("error", e.errorCode, "message", e.getMessage()));
   145	        }
   146	      }
   147	    });
   148	
   149	    app.post("/reservations/:id/check-out", ctx -> {
   150	      try {
   151	        long id = Long.parseLong(ctx.pathParam("id"));
   152	        Document document = reservationService.checkOut(id);
   153	        ctx.json(documentToJson(document));
   154	      } catch (NumberFormatException e) {
   155	        ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid reservation ID"));
   156	      } catch (RatePlanStrategy.InvalidReservationException e) {
   157	        if (e.errorCode.equals("RESERVATION_NOT_FOUND")) {
   158	          ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", e.getMessage()));
   159	        } else {
   160	          ctx.status(409).json(Map.of("error", e.errorCode, "message", e.getMessage()));
   161	        }
   162	      }
   163	    });
   164	
   165	    app.get("/reservations/:id/document", ctx -> {
   166	      try {
   167	        long id = Long.parseLong(ctx.pathParam("id"));
   168	        Document document = reservationService.getDocument(id);
   169	        ctx.json(documentToJson(document));
   170	      } catch (NumberFormatException e) {
   171	        ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid reservation ID"));
   172	      } catch (RatePlanStrategy.InvalidReservationException e) {
   173	        if (e.errorCode.equals("RESERVATION_NOT_FOUND")) {
   174	          ctx.status(404).json(Map.of("error", "RESERVATION_NOT_FOUND", "message", e.getMessage()));
   175	        } else {
   176	          ctx.status(409).json(Map.of("error", e.errorCode, "message", e.getMessage()));
   177	        }
   178	      }
   179	    });
   180	  }
   181	
   182	  private static Map<String, Object> toJson(Reservation r) {
   183	    Map<String, Object> map = new HashMap<>();
   184	    map.put("id", r.getId());
   185	    map.put("roomNumber", r.getRoomNumber());
   186	    map.put("guestName", r.getGuestName());
   187	    map.put("guestEmail", r.getGuestEmail());
   188	    map.put("guestCpf", r.getGuestCpf());
   189	    map.put("checkIn", r.getCheckIn().toString());
   190	    map.put("checkOut", r.getCheckOut().toString());
   191	    map.put("guests", r.getGuests());
   192	    map.put("ratePlan", r.getRatePlan().toString());
   193	    map.put("nights", r.getNights());
   194	    map.put("subtotal", r.getSubtotal());
   195	    map.put("discount", r.getDiscount());
   196	    map.put("total", r.getTotal());
   197	    map.put("status", r.getStatus().toString());
   198	    map.put("amountPaid", r.getAmountPaid());
   199	    map.put("refund", r.getRefund());
   200	    return map;
   201	  }
   202	
   203	  private static Map<String, Object> documentToJson(Document d) {
   204	    Map<String, Object> map = new HashMap<>();
   205	    map.put("title", d.getTitle());
   206	    map.put("reservationId", d.getReservationId());
   207	    map.put("guestName", d.getGuestName());
   208	    map.put("guestCpf", d.getGuestCpf());
   209	    map.put("roomNumber", d.getRoomNumber());
   210	    map.put("roomType", d.getRoomType());
   211	    map.put("checkIn", d.getCheckIn().toString());
   212	    map.put("checkOut", d.getCheckOut().toString());
   213	    map.put("nights", d.getNights());
   214	    map.put("subtotal", d.getSubtotal());
   215	    map.put("discount", d.getDiscount());
   216	    map.put("total", d.getTotal());
   217	    return map;
   218	  }
   219	}
