    16	  public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    17	    this.reservationRepository = reservationRepository;
    18	    this.roomRepository = roomRepository;
    19	  }
    20	
    21	  public String occupancyReport(LocalDate date) {
    22	    StringBuilder csv = new StringBuilder();
    23	    csv.append("room,type,reservation,check_in,check_out\n");
    24	
    25	    List<Room> rooms = roomRepository.findAll();
    26	    int occupiedCount = 0;
    27	
    28	    for (Room room : rooms) {
    29	      List<Reservation> reservations = reservationRepository.findConfirmedByRoomAndDate(room.getNumber(), date);
    30	      if (!reservations.isEmpty()) {
    31	        for (Reservation res : reservations) {
    32	          csv.append(room.getNumber()).append(",")
    33	              .append(room.getType()).append(",")
    34	              .append(res.getId()).append(",")
    35	              .append(formatDate(res.getCheckIn())).append(",")
    36	              .append(formatDate(res.getCheckOut())).append("\n");
    37	        }
    38	        occupiedCount++;
    39	      }
    40	    }
    41	
    42	    csv.append("total,").append(occupiedCount).append("/").append(rooms.size()).append("\n");
    43	
    44	    return csv.toString();
    45	  }
    46	
    47	  public String revenueReport(int year, int month) {
    48	    StringBuilder csv = new StringBuilder();
    49	    csv.append("reservation,room,check_in,check_out,status,amount\n");
    50	
    51	    List<Reservation> reservations = reservationRepository.findByMonthWithRevenue(year, month);
    52	    BigDecimal totalRevenue = BigDecimal.ZERO;
    53	
    54	    for (Reservation res : reservations) {
    55	      BigDecimal revenue = res.getAmountPaid();
    56	      if (res.getRefund() != null) {
    57	        revenue = revenue.subtract(res.getRefund());
    58	      }
    59	
    60	      csv.append(res.getId()).append(",")
    61	          .append(res.getRoomNumber()).append(",")
    62	          .append(formatDate(res.getCheckIn())).append(",")
    63	          .append(formatDate(res.getCheckOut())).append(",")
    64	          .append(res.getStatus()).append(",")
    65	          .append(formatMoney(revenue)).append("\n");
    66	
    67	      totalRevenue = totalRevenue.add(revenue);
    68	    }
    69	
    70	    csv.append("total,,,,").append(formatMoney(totalRevenue)).append("\n");
    71	
    72	    return csv.toString();
    73	  }
    74	
    75	  private String formatDate(LocalDate date) {
    76	    return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
    77	  }
    78	
    79	  private String formatMoney(BigDecimal amount) {
    80	    return String.format("%.2f", amount);
    81	  }
    82	}
