    30	  public Reservation createReservation(
    31	      int roomNumber,
    32	      String guestName,
    33	      String guestEmail,
    34	      String guestCpf,
    35	      LocalDate checkIn,
    36	      LocalDate checkOut,
    37	      int guests,
    38	      Reservation.RatePlan ratePlan,
    39	      String companyCode)
    40	      throws RatePlanStrategy.InvalidReservationException {
    41	    Optional<Room> room = roomRepository.findById(roomNumber);
    42	    if (room.isEmpty()) {
    43	      throw new RatePlanStrategy.InvalidReservationException("Room not found", "ROOM_NOT_FOUND");
    44	    }
    45	
    46	    Room r = room.get();
    47	
    48	    if (checkIn.isAfter(checkOut) || checkIn.equals(checkOut)) {
    49	      throw new RatePlanStrategy.InvalidReservationException("Invalid dates", "INVALID_REQUEST");
    50	    }
    51	
    52	    if (!reservationRepository.findByRoomAndDates(roomNumber, checkIn, checkOut).isEmpty()) {
    53	      throw new RatePlanStrategy.InvalidReservationException("Room unavailable for these dates", "ROOM_UNAVAILABLE");
    54	    }
    55	
    56	    RatePlanStrategy strategy = RatePlanFactory.create(ratePlan);
    57	    strategy.validate(r, checkIn, checkOut, guests, companyCode);
    58	
    59	    RatePlanStrategy.PriceCalculation pricing;
    60	    if (ratePlan == Reservation.RatePlan.CORPORATE) {
    61	      pricing = strategy.calculatePrice(r, checkIn, checkOut, companyCode);
    62	    } else {
    63	      pricing = strategy.calculatePrice(r, checkIn, checkOut);
    64	    }
    65	
    66	    Reservation reservation = new Reservation();
    67	    reservation.setRoomNumber(roomNumber);
    68	    reservation.setGuestName(guestName);
    69	    reservation.setGuestEmail(guestEmail);
    70	    reservation.setGuestCpf(guestCpf);
    71	    reservation.setCheckIn(checkIn);
    72	    reservation.setCheckOut(checkOut);
    73	    reservation.setGuests(guests);
    74	    reservation.setRatePlan(ratePlan);
    75	    reservation.setCompanyCode(companyCode);
    76	    reservation.setNights(pricing.nights);
    77	    reservation.setSubtotal(pricing.subtotal);
    78	    reservation.setDiscount(pricing.discount);
    79	    reservation.setTotal(pricing.total);
    80	    reservation.setStatus(Reservation.Status.PENDING);
    81	    reservation.setAmountPaid(BigDecimal.ZERO);
    82	    reservation.setRefund(null);
    83	
    84	    return reservationRepository.save(reservation);
    85	  }
