    87	  public Reservation confirmReservation(long reservationId, BigDecimal amountPaid)
    88	      throws RatePlanStrategy.InvalidReservationException {
    89	    Optional<Reservation> reservation = reservationRepository.findById(reservationId);
    90	    if (reservation.isEmpty()) {
    91	      throw new RatePlanStrategy.InvalidReservationException("Reservation not found", "RESERVATION_NOT_FOUND");
    92	    }
    93	
    94	    Reservation r = reservation.get();
    95	    if (r.getStatus() != Reservation.Status.PENDING) {
    96	      throw new RatePlanStrategy.InvalidReservationException(
    97	          "Operation not allowed for this reservation status", "OPERATION_NOT_ALLOWED");
    98	    }
    99	
   100	    r.setStatus(Reservation.Status.CONFIRMED);
   101	    r.setAmountPaid(amountPaid);
   102	    reservationRepository.update(r);
   103	
   104	    sendConfirmationEmail(r);
   105	
   106	    return r;
   107	  }
