   151	    if (r.getStatus() == Reservation.Status.PENDING || r.getStatus() == Reservation.Status.CANCELLED) {
   152	      throw new RatePlanStrategy.InvalidReservationException(
   153	          "Document not available for this reservation", "OPERATION_NOT_ALLOWED");
   154	    }
   155	
   156	    return new Document(
   157	        r.getId(),
   158	        r.getGuestName(),
   159	        r.getGuestCpf(),
   160	        r.getRoomNumber(),
   161	        getRoomType(r.getRoomNumber()),
   162	        r.getCheckIn(),
   163	        r.getCheckOut(),
   164	        r.getNights(),
   165	        r.getSubtotal(),
   166	        r.getDiscount(),
   167	        r.getTotal());
   168	  }
   169	
   170	  public Reservation checkIn(long reservationId) throws RatePlanStrategy.InvalidReservationException {
   171	    Optional<Reservation> reservation = reservationRepository.findById(reservationId);
   172	    if (reservation.isEmpty()) {
   173	      throw new RatePlanStrategy.InvalidReservationException("Reservation not found", "RESERVATION_NOT_FOUND");
   174	    }
   175	
   176	    Reservation r = reservation.get();
   177	    if (r.getStatus() != Reservation.Status.CONFIRMED) {
   178	      throw new RatePlanStrategy.InvalidReservationException(
   179	          "Operation not allowed for this reservation status", "OPERATION_NOT_ALLOWED");
   180	    }
   181	
   182	    r.setStatus(Reservation.Status.CHECKED_IN);
   183	    reservationRepository.update(r);
   184	
   185	    return r;
   186	  }
   187	
   188	  public Document checkOut(long reservationId) throws RatePlanStrategy.InvalidReservationException {
   189	    Optional<Reservation> reservation = reservationRepository.findById(reservationId);
   190	    if (reservation.isEmpty()) {
   191	      throw new RatePlanStrategy.InvalidReservationException("Reservation not found", "RESERVATION_NOT_FOUND");
   192	    }
   193	
   194	    Reservation r = reservation.get();
   195	    if (r.getStatus() != Reservation.Status.CHECKED_IN) {
   196	      throw new RatePlanStrategy.InvalidReservationException(
   197	          "Operation not allowed for this reservation status", "OPERATION_NOT_ALLOWED");
   198	    }
   199	
   200	    r.setStatus(Reservation.Status.CHECKED_OUT);
   201	    reservationRepository.update(r);
   202	
   203	    return new Document(
   204	        r.getId(),
   205	        r.getGuestName(),
   206	        r.getGuestCpf(),
   207	        r.getRoomNumber(),
   208	        getRoomType(r.getRoomNumber()),
   209	        r.getCheckIn(),
   210	        r.getCheckOut(),
   211	        r.getNights(),
   212	        r.getSubtotal(),
   213	        r.getDiscount(),
   214	        r.getTotal());
   215	  }
   216	
   217	  public Reservation cancel(long reservationId) throws RatePlanStrategy.InvalidReservationException {
   218	    Optional<Reservation> reservation = reservationRepository.findById(reservationId);
   219	    if (reservation.isEmpty()) {
   220	      throw new RatePlanStrategy.InvalidReservationException("Reservation not found", "RESERVATION_NOT_FOUND");
   221	    }
   222	
   223	    Reservation r = reservation.get();
   224	    if (r.getStatus() != Reservation.Status.PENDING && r.getStatus() != Reservation.Status.CONFIRMED) {
   225	      throw new RatePlanStrategy.InvalidReservationException(
   226	          "Operation not allowed for this reservation status", "OPERATION_NOT_ALLOWED");
   227	    }
   228	
   229	    RatePlanStrategy strategy = RatePlanFactory.create(r.getRatePlan());
   230	    BigDecimal refund = strategy.calculateRefund(r.getAmountPaid());
   231	
   232	    r.setStatus(Reservation.Status.CANCELLED);
   233	    r.setRefund(refund);
   234	    reservationRepository.update(r);
   235	
   236	    return r;
   237	  }
   238	
   239	  private String getRoomType(int roomNumber) {
   240	    Optional<Room> room = roomRepository.findById(roomNumber);
   241	    return room.map(r -> r.getType().toString()).orElse("UNKNOWN");
   242	  }
   243	
   244	  private String formatDocument(Document doc) {
   245	    StringBuilder sb = new StringBuilder();
   246	    sb.append("Comprovante de reserva nº ").append(doc.getReservationId()).append("\n");
   247	    sb.append("Hóspede: ").append(doc.getGuestName()).append(" (CPF ").append(formatCpf(doc.getGuestCpf()))
   248	        .append(")\n");
   249	    sb.append("Quarto: ").append(doc.getRoomNumber()).append(" (").append(doc.getRoomType()).append(")\n");
   250	    sb.append("Entrada: ").append(formatDate(doc.getCheckIn())).append(" | Saída: ")
   251	        .append(formatDate(doc.getCheckOut())).append(" | ").append(doc.getNights())
   252	        .append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
   253	    sb.append("Diárias: ").append(formatMoney(doc.getSubtotal())).append("\n");
   254	    if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   255	      sb.append("Desconto: ").append(formatMoney(doc.getDiscount())).append("\n");
   256	    }
   257	    sb.append("Total: ").append(formatMoney(doc.getTotal())).append("\n");
   258	
   259	    return sb.toString();
   260	  }
   261	
   262	  private String formatDate(LocalDate date) {
   263	    return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
   264	  }
   265	
   266	  private String formatMoney(BigDecimal amount) {
   267	    return String.format("R$ %,.2f", amount).replace(",", ".");
   268	  }
   269	
   270	  private String formatCpf(String cpf) {
   271	    if (cpf == null || cpf.length() < 11) return cpf;
   272	    return String.format("%s.%s.%s-%s", cpf.substring(0, 3), cpf.substring(3, 6), cpf.substring(6, 9),
   273	        cpf.substring(9));
   274	  }
   275	}
