    11	public class CorporateRatePlan implements RatePlanStrategy {
    12	  private static final Map<String, Integer> COMPANY_DISCOUNTS = Map.of(
    13	      "TECNOSUL", 12,
    14	      "AGROVALE", 18,
    15	      "FARMAVIDA", 25
    16	  );
    17	
    18	  @Override
    19	  public void validate(Room room, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode)
    20	      throws InvalidReservationException {
    21	    if (companyCode == null || companyCode.isBlank() || !COMPANY_DISCOUNTS.containsKey(companyCode)) {
    22	      throw new InvalidReservationException("Invalid or missing company code", "INVALID_REQUEST");
    23	    }
    24	
    25	    if (guests < 1 || guests > room.getCapacity()) {
    26	      throw new InvalidReservationException("Invalid number of guests", "CAPACITY_EXCEEDED");
    27	    }
    28	  }
    29	
    30	  @Override
    31	  public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    32	    int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    33	    BigDecimal subtotal = BigDecimal.ZERO;
    34	
    35	    for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
    36	      BigDecimal nightRate = room.getNightlyRate();
    37	      if (Season.isHighSeason(date)) {
    38	        nightRate = Money.multiply(nightRate, BigDecimal.valueOf(1.2));
    39	      }
    40	      subtotal = Money.add(subtotal, nightRate);
    41	    }
    42	
    43	    int discountPercent = COMPANY_DISCOUNTS.get(companyCode);
    44	    BigDecimal discount = Money.percentage(subtotal, discountPercent);
    45	    BigDecimal total = Money.subtract(subtotal, discount);
    46	
    47	    return new PriceCalculation(nights, subtotal, discount, total);
    48	  }
