    50	  @Override
    51	  public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut)
    52	      throws InvalidReservationException {
    53	    throw new InvalidReservationException("Corporate plan requires company code", "INVALID_REQUEST");
    54	  }
