     9	  public static BigDecimal round(BigDecimal value) {
    10	    return value.setScale(SCALE, RoundingMode.HALF_EVEN);
    11	  }
    12	
    13	  public static BigDecimal add(BigDecimal a, BigDecimal b) {
    14	    return round(a.add(b));
    15	  }
    16	
    17	  public static BigDecimal subtract(BigDecimal a, BigDecimal b) {
    18	    return round(a.subtract(b));
    19	  }
    20	
    21	  public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
    22	    return round(a.multiply(b));
    23	  }
    24	
    25	  public static BigDecimal percentage(BigDecimal value, int percent) {
    26	    return multiply(value, BigDecimal.valueOf(percent).divide(BigDecimal.valueOf(100)));
    27	  }
