     1	package com.pousada.infrastructure;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	
     6	import java.sql.Connection;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	
    10	public class Database {
    11	  private static HikariDataSource dataSource;
    12	
    13	  public static void initialize() {
    14	    String dbUrl = System.getenv("DB_URL");
    15	    String dbUser = System.getenv("DB_USER");
    16	    String dbPassword = System.getenv("DB_PASSWORD");
    17	
    18	    if (dbUrl == null || dbUser == null || dbPassword == null) {
    19	      throw new IllegalStateException("DB_URL, DB_USER, and DB_PASSWORD environment variables are required");
    20	    }
    21	
    22	    HikariConfig config = new HikariConfig();
    23	    config.setJdbcUrl(dbUrl);
    24	    config.setUsername(dbUser);
    25	    config.setPassword(dbPassword);
    26	    config.setMaximumPoolSize(10);
    27	
    28	    dataSource = new HikariDataSource(config);
    29	
    30	    createSchema();
    31	  }
    32	
    33	  private static void createSchema() {
    34	    try (Connection conn = dataSource.getConnection(); Statement stmt = conn.createStatement()) {
    35	      stmt.execute(
    36	          """
    37	          CREATE TABLE IF NOT EXISTS rooms (
    38	              number INTEGER PRIMARY KEY,
    39	              type VARCHAR(20) NOT NULL,
    40	              capacity INTEGER NOT NULL,
    41	              nightly_rate NUMERIC(10, 2) NOT NULL
    42	          )
    43	          """);
    44	
    45	      stmt.execute(
    46	          """
    47	          CREATE TABLE IF NOT EXISTS reservations (
    48	              id SERIAL PRIMARY KEY,
    49	              room_number INTEGER NOT NULL REFERENCES rooms(number),
    50	              guest_name VARCHAR(255) NOT NULL,
    51	              guest_email VARCHAR(255) NOT NULL,
    52	              guest_cpf VARCHAR(20) NOT NULL,
    53	              check_in DATE NOT NULL,
    54	              check_out DATE NOT NULL,
    55	              guests INTEGER NOT NULL,
    56	              rate_plan VARCHAR(50) NOT NULL,
    57	              company_code VARCHAR(50),
    58	              nights INTEGER NOT NULL,
    59	              subtotal NUMERIC(10, 2) NOT NULL,
    60	              discount NUMERIC(10, 2),
    61	              total NUMERIC(10, 2) NOT NULL,
    62	              status VARCHAR(20) NOT NULL,
    63	              amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
    64	              refund NUMERIC(10, 2)
    65	          )
    66	          """);
    67	
    68	      stmt.execute(
    69	          """
    70	          CREATE TABLE IF NOT EXISTS messages (
    71	              id SERIAL PRIMARY KEY,
    72	              channel VARCHAR(50) NOT NULL,
    73	              "to" VARCHAR(255) NOT NULL,
    74	              subject VARCHAR(255) NOT NULL,
    75	              body TEXT NOT NULL
    76	          )
    77	          """);
    78	
    79	      insertRoomsIfEmpty();
    80	    } catch (SQLException e) {
    81	      throw new RuntimeException("Failed to create schema", e);
    82	    }
    83	  }
    84	
    85	  private static void insertRoomsIfEmpty() {
